# The web e2e suite (blueprint/testing.md), in two slices: `smoke` is the PR
# gate's bounded-minutes budget, `full` is the main gate's whole suite. The
# suite runs against the production static build, so it needs the engine WASM: a
# caller passes `wasm-artifact` to hand over the module its run already built,
# and a caller that does not gets the module built here. It builds the bundle
# twice: once as it ships, once with `VITE_E2E_HOOK` for the introspection seam.
# The suite asserts the shipping one carries no hook.
name: Web E2E Tests

on:
  workflow_dispatch:
    inputs:
      suite:
        description: Which slice to run
        required: false
        default: smoke
        type: choice
        options: [smoke, full]
  workflow_call:
    inputs:
      ref:
        description: 'Git ref to checkout (tag, branch, or SHA)'
        required: false
        type: string
      wasm-artifact:
        description: >-
          Name of a run artifact holding a prebuilt engine WASM module. Set it
          and the suite tests exactly those bytes; leave it empty and this job
          builds the module itself, which is what a standalone dispatch needs.
        required: false
        default: ''
        type: string
      suite:
        description: >-
          Which slice to run: `smoke` drops every `@full`-tagged spec and holds
          the PR gate's minutes budget; `full` runs the whole suite.
        required: false
        default: smoke
        type: string

permissions: {}

jobs:
  web-e2e:
    # Both callers get the name their slice earns, and `smoke` renders exactly
    # the name branch protection already knows.
    name: Web E2E ${{ inputs.suite == 'full' && 'Full' || 'Smoke' }}
    runs-on: ubuntu-latest
    # The suite itself runs in seconds; the budget covers a standalone
    # dispatch, where a cold-cache wasm build runs ahead of it.
    timeout-minutes: 45
    permissions:
      contents: read

    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_USER: postgres
          POSTGRES_PASSWORD: postgres
